def enrich(e,p,prev):
 e=base.make(e,p,prev)
 words=[x[0] for x in p['v']]
 for f in e['fr']:
  if f.get('k')=='pgsheet' and f.get('title')=='Palavras da cena':
   for i,c in enumerate(f['items']): c['opts']=[words[i],words[(i+1)%6],words[(i+2)%6]]; c['a']=0
  if f.get('k')=='pgsheet' and f.get('title') in ('Complete as falas','Qual está certa?','Caça-sons'):
   for q in f.get('items',[]): q['opts']=[x for x in q.get('opts',[]) if x not in ('outra palavra','outra forma','outra opção')]
  if f.get('k')=='verbs':
   for i,it in enumerate(f['items']):
    it['pt']=p['vb'][i]; it['f']=[['eu',p['s1'][i*2][1]],['ele/ela',p['s1'][i*2+1][1]]]; it['ex']=[p['s1'][i*2][1],p['s1'][i*2][2]]; it['v']=p['vb'][i]; it['note']=f'Use **{p["vb"][i]}** para falar de {p["focus"]}.'
   f['quiz']=[{'text':f'Escolha o verbo usado na cena: {p["s1"][i*2][1]}','opts':[p['vb'][i],p['vb'][(i+1)%4],p['vb'][(i+2)%4]],'a':0,'why':f'**{p["vb"][i]}** completa a situação.'} for i in range(4)]
  if f.get('k')=='pgexp':
   for i,q in enumerate(f.get('quiz',[])):
    q['opts']=[p['ex'][i*2+1],p['ex'][((i+1)%4)*2+1],p['ex'][((i+2)%4)*2+1]]; q['a']=0
 e['t']=p['t']; e['s']=f'Hispanoamérica · {p["focus"]} · referencia: {p["work"]}'
 e['a']={'k':'🎬 Obra','w':p['work'],'y':p['year'],'d':p['desc']}
 e['h']['src']=p['work']; e['h']['l']=p['s1'][0][1]; e['h']['tr']=p['s1'][0][2]
 e['p']=f'Hoje você aprende a {p["focus"]}, em uma situação inspirada por **{p["work"]}**.'
 return e

data=json.loads(PATH.read_text(encoding='utf-8')); by={e['n']:e for e in data}; prev=by[278]
for p in PLANS:
 by[p['n']]=enrich(by[p['n']],p,prev); prev=by[p['n']]
PATH.write_text(json.dumps([by[e['n']] for e in data],ensure_ascii=False,separators=(',',':')),encoding='utf-8')
print('wrote', [p['n'] for p in PLANS])
